 import unittest
from candidate import greatest_common_divisor

class TestGCD(unittest.TestCase):
    def test_gcd_positive_numbers(self):
        self.assertEqual(greatest_common_divisor(3, 5), 1)

    def test_gcd_negative_numbers(self):
        self.assertEqual(greatest_common_divisor(-3, -5), 1)

    def test_gcd_with_zero(self):
        self.assertEqual(greatest_common_divisor(0, 5), 0)
        self.assertEqual(greatest_common_divisor(5, 0), 0)
        self.assertEqual(greatest_common_divisor(0, 0), 0)

    def test_gcd_with_one(self):
        self.assertEqual(greatest_common_divisor(1, 5), 1)
        self.assertEqual(greatest_common_divisor(5, 1), 1)

    def test_gcd_boundary_cases(self):
        self.assertEqual(greatest_common_divisor(2147483647, 1), 1)
        self.assertEqual(greatest_common_divisor(-2147483648, 1), 1)
        self.assertEqual(greatest_common_divisor(2147483647, -1), 1)
        self.assertEqual(greatest_common_divisor(-2147483648, -1), 1)

    def test_gcd_empty_inputs(self):
        self.assertRaises(TypeError, greatest_common_divisor, None, None)
        self.assertRaises(TypeError, greatest_common_divisor, 3.14, "string")

    def test_gcd_type_errors(self):
        self.assertRaises(TypeError, greatest_common_divisor, "string", 5)
        self.assertRaises(TypeError, greatest_common_divisor, 5, "string")

if __name__ == '__main__':
    unittest.main()
